using System;using System.Linq;using System.Collections.Generic;using System.Reflection;using LWS.TruckPoker;
namespace LWS.TruckPoker.Editor {public static class PokerFixtures {
 static bool Exhaustive;
 static int count;static readonly List<string> log=new List<string>();static void Check(bool ok,string name){if(!ok)throw new Exception("FAIL "+name);count++;log.Add("PASS "+name);}
 static int C(string name){int r="23456789TJQKA".IndexOf(name[0]),s="cdhs".IndexOf(name[1]);return s*13+r;}static long H(params string[] names)=>PokerHand.Evaluate(names.Select(C).ToArray());
 static void Act(PokerTable t,PokerAction action,int total=0){int seat=t.Actor;if(!t.Act(seat,action,total,out string error))throw new Exception("Illegal test action "+action+" "+total+" actor="+seat+" reason="+error);}
 static void HandTests(){long[] ranks={H("Ac","Jd","9h","6s","3c"),H("Ac","Ad","9h","6s","3c"),H("Ac","Ad","9h","9s","3c"),H("Ac","Ad","Ah","6s","3c"),H("2c","3d","4h","5s","6c"),H("Ac","Jc","9c","6c","3c"),H("Ac","Ad","Ah","6s","6c"),H("Ac","Ad","Ah","As","3c"),H("Tc","Jc","Qc","Kc","Ac")};for(int i=0;i<9;i++){Check((ranks[i]>>20)==i,"category "+i);if(i>0)Check(ranks[i]>ranks[i-1],"category order "+i);}Check(H("Ac","2d","3h","4s","5c")<H("2c","3d","4h","5s","6c"),"wheel loses to six-high straight");Check(H("Ac","Ad","Ah","Kc","Kd","Kh","2s")==H("Ac","Ad","Ah","Kc","Kd"),"best full house from two trips");Check(H("Ac","Kd","Qh","Js","Tc","2d","3h")==H("Ad","Kh","Qs","Jc","Td","4s","5s"),"board-equivalent straight tie");bool rejected=false;try{PokerHand.Evaluate(0,0,1,2,3);}catch(ArgumentException){rejected=true;}Check(rejected,"duplicate card rejected");
 if(!Exhaustive)return;long[] expected={1302540,1098240,123552,54912,10200,5108,3744,624,40};long[] categories=new long[9];for(int a=0;a<48;a++)for(int b=a+1;b<49;b++)for(int c=b+1;c<50;c++)for(int d=c+1;d<51;d++)for(int e=d+1;e<52;e++)categories[PokerHand.Evaluate(a,b,c,d,e)>>20]++;for(int i=0;i<9;i++)Check(categories[i]==expected[i],"exhaustive 2,598,960 five-card category count "+i);}
 static void PotTests(){var paid=PokerPots.Settle(new[]{100,200,300},new[]{false,false,false},new long[]{9,8,7},0,out var returns,out var awards);Check(paid.SequenceEqual(new[]{300,200,100})&&returns[2]==100&&awards.Length==2,"all-in main/side pots and uncalled excess");paid=PokerPots.Settle(new[]{100,100,100},new[]{true,false,false},new long[]{99,4,3},1,out returns,out awards);Check(paid.SequenceEqual(new[]{0,300,0}),"folded highest rank ineligible");paid=PokerPots.Settle(new[]{5,5,5},new[]{false,false,true},new long[]{8,8,0},0,out returns,out awards);Check(paid.SequenceEqual(new[]{7,8,0}),"odd chip goes to first tied winner left of button");paid=PokerPots.Settle(new[]{50,150,150,300},new[]{false,true,false,false},new long[]{8,99,9,7},3,out returns,out awards);Check(paid.Sum()==650&&paid[1]==0&&returns[3]==150&&paid[2]==500,"folded contribution funds eligible side pot with total conservation");}
 static void BettingTests(){var t=new PokerTable(new[]{1000,1000},41);Check(t.BeginHand()&&t.Button==t.SmallBlindSeat&&t.Actor==t.Button,"heads-up button is small blind and acts first preflop");Act(t,PokerAction.CheckCall);Check(t.Actor==t.BigBlindSeat&&t.View(t.Actor).Call==0,"big blind retains option after limp");Act(t,PokerAction.CheckCall);Check(t.Street==PokerStreet.Flop&&t.Actor==t.BigBlindSeat,"heads-up big blind acts first after flop");Act(t,PokerAction.CheckCall);Act(t,PokerAction.CheckCall);Check(t.Street==PokerStreet.Turn,"checks close street exactly once");while(!t.HandDone)Act(t,PokerAction.CheckCall);int oldButton=t.Button;Check(t.BeginHand()&&t.Button!=oldButton,"heads-up button alternates");
 t=new PokerTable(new[]{1000,1000,1000},42);t.BeginHand();int actor=t.Actor;Check(t.MinimumRaise==40,"preflop full raise minimum");Check(!t.Act(actor,PokerAction.RaiseTo,30,out _)&&t.Actor==actor,"non-allin underraise rejected without progression");Act(t,PokerAction.RaiseTo,40);Check(t.MinimumRaise==60&&t.LastFullRaise==20,"full raise defines next minimum");
 t=new PokerTable(new[]{1000,50,1000},43);t.BeginHand();Act(t,PokerAction.RaiseTo,40);Act(t,PokerAction.RaiseTo,50);Act(t,PokerAction.CheckCall);Check(t.Actor==0&&!t.RaiseAllowed(0,out _)&&t.View(0).Call==10,"single short all-in does not reopen original raiser");Act(t,PokerAction.CheckCall);Check(t.Street==PokerStreet.Flop,"short all-in call closes preflop without extra action");
 t=new PokerTable(new[]{1000,50,60,1000},44);t.BeginHand();Act(t,PokerAction.RaiseTo,40);Act(t,PokerAction.CheckCall);Act(t,PokerAction.RaiseTo,50);Act(t,PokerAction.RaiseTo,60);Check(t.Actor==3&&t.RaiseAllowed(3,out _),"cumulative short all-ins reopen after full increment faced");
 t=new PokerTable(new[]{1000,5},45);t.BeginHand();Check(t.HandDone&&t.PublicBoard.Length==5&&t.Returns[0]>=5&&t.Stack(0)+t.Stack(1)==1005,"short heads-up big blind has no phantom full-blind call");
 t=new PokerTable(new[]{100,100,5},46);t.BeginHand();Check(t.Actor==0&&t.View(0).Call==20,"multiway short big blind still has full bring-in");Act(t,PokerAction.CheckCall);Act(t,PokerAction.CheckCall);Check(t.Street==PokerStreet.Flop,"multiway short blind proceeds normally");
 t=new PokerTable(new[]{1000,1000,1000},47);t.BeginHand();while(t.Street==PokerStreet.Preflop)Act(t,PokerAction.CheckCall);int first=t.Actor;Act(t,PokerAction.CheckCall);Act(t,PokerAction.RaiseTo,20);Act(t,PokerAction.CheckCall);Check(t.Actor==first&&t.RaiseAllowed(first,out _),"full opening bet reopens a prior checker");
 t=new PokerTable(new[]{1000,1000,1000},48);t.BeginHand();int before=t.Pot;Act(t,PokerAction.RaiseTo,100);Act(t,PokerAction.Fold);Act(t,PokerAction.Fold);Check(t.HandDone&&t.Returns[0]==80&&t.LastPayout[0]>0,"fold win returns unique uncalled raise");
 }
 static void MoreBetting(){var t=new PokerTable(new[]{25,1000,1000},818);t.BeginHand();while(t.Street==PokerStreet.Preflop)Act(t,PokerAction.CheckCall);Act(t,PokerAction.CheckCall);Act(t,PokerAction.CheckCall);Act(t,PokerAction.RaiseTo,5);Check(t.Actor==1&&!t.RaiseAllowed(1,out _)&&t.MinimumRaise==25,"incomplete five-chip opening does not reopen prior checker under TDA49");while(!t.HandDone)Act(t,PokerAction.CheckCall);Check(Enumerable.Range(0,3).Where(i=>!t.IsFolded(i)).All(t.PubliclyRevealed),"all-in showdown tables all surviving hands");t=new PokerTable(new[]{100,100,100},819);t.BeginHand();while(!t.HandDone)Act(t,PokerAction.CheckCall);var required=t.Awards.SelectMany(a=>a.Winners).Distinct().ToArray();Check(Enumerable.Range(0,3).All(i=>t.PubliclyRevealed(i)==required.Contains(i)),"ordinary showdown reveals required winners, other hands muck privately");t=new PokerTable(new[]{100,100,100},820);t.BeginHand();Act(t,PokerAction.Fold);Act(t,PokerAction.Fold);Check(Enumerable.Range(0,3).All(i=>!t.PubliclyRevealed(i)),"fold victory never exposes private hands");}
 static void Policies(){for(int seats=2;seats<=8;seats+=3)for(int level=0;level<3;level++){var t=new PokerTable(Enumerable.Repeat(300,seats).ToArray(),4700+seats*31+level,5,4);var personal=new Random[seats];for(int i=0;i<seats;i++)personal[i]=new Random(9500+i*701+level);int hands=0,actions=0;while(t.Winner<0&&hands<160){t.BeginHand();hands++;while(!t.HandDone&&actions<10000){int seat=t.Actor;var decision=PokerPolicy.Choose(t.View(seat),level,personal[seat]);Act(t,decision.Action,decision.Total);actions++;t.CheckChips();}}Check(t.Winner>=0&&actions<10000,"legal own-snapshot AI tournament n="+seats+" difficulty="+level+" hands="+hands+" actions="+actions);}}
 static void Tournaments(){for(int seats=2;seats<=8;seats++)for(int seed=0;seed<12;seed++){var t=new PokerTable(Enumerable.Repeat(300,seats).ToArray(),seed*31+seats,5,3);var random=new Random(9000+seed);int hands=0,actions=0;while(t.Winner<0&&hands<220){Check(t.BeginHand(),"tournament hand starts n="+seats+" seed="+seed+" hand="+hands);hands++;while(!t.HandDone&&actions<30000){actions++;var v=t.View(t.Actor);PokerAction action=PokerAction.CheckCall;int amount=0;int decision=random.Next(8);if(decision==0&&v.Call>0)action=PokerAction.Fold;else if(decision<4&&v.CanRaise){action=PokerAction.RaiseTo;amount=decision==1?v.MaximumRaiseTo:Math.Min(v.MaximumRaiseTo,v.MinimumRaiseTo);}Act(t,action,amount);t.CheckChips();}if(!t.HandDone)throw new Exception("Tournament action stall");}Check(t.Winner>=0&&Enumerable.Range(0,seats).Count(i=>t.Stack(i)>0)==1&&Enumerable.Range(0,seats).Sum(t.Stack)==seats*300,"complete conserved tournament n="+seats+" seed="+seed+" hands="+hands);}}
 static void Boundary(){var t=new PokerTable(new[]{100,100,100},71);t.BeginHand();var v=t.View(t.Actor);int original=t.Stack(0);v.Stacks[0]=987654;Check(t.Stack(0)==original,"public snapshot mutation cannot alter engine");var policyFields=typeof(PokerPolicy).GetFields(BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Static|BindingFlags.Instance);Check(policyFields.All(f=>f.FieldType!=typeof(PokerTable)),"AI policy owns no table or deck authority");var viewFields=typeof(PokerView).GetFields(BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance);Check(viewFields.All(f=>f.FieldType!=typeof(PokerTable)&&f.FieldType!=typeof(Random))&&viewFields.All(f=>!f.Name.ToLowerInvariant().Contains("deck")),"AI snapshot contains no engine, deck or shuffle state");}
 public static int Run(bool exhaustive=false){Exhaustive=exhaustive;count=0;log.Clear();HandTests();PotTests();BettingTests();MoreBetting();Boundary();if(exhaustive){Tournaments();Policies();}UnityEngine.Debug.Log("POKER_CORE_FIXTURES_PASS checks="+count+" exhaustive="+exhaustive);return count;}
}}
